const item = $input.first().json;
let rawReply = item.output || item.text || "";

let cleanReply = rawReply;
let plano = null;
let finalizado = false;

// 1. Tenta extrair da tag [PROPOSTA_PLANO]...[/PROPOSTA_PLANO]
const tagMatch = rawReply.match(/\[PROPOSTA_PLANO\]\s*([\s\S]*?)\s*\[\/PROPOSTA_PLANO\]/i);
if (tagMatch && tagMatch[1]) {
  try {
    plano = JSON.parse(tagMatch[1]);
    if (plano && plano.finalizado) finalizado = true;
    cleanReply = rawReply.replace(/\[PROPOSTA_PLANO\][\s\S]*?\[\/PROPOSTA_PLANO\]/gi, "").trim();
  } catch (e) {}
}

// 2. Se não achou na tag, tenta extrair de bloco de código markdown
if (!plano) {
  const jsonMatch = rawReply.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
  if (jsonMatch && jsonMatch[1]) {
    try {
      plano = JSON.parse(jsonMatch[1]);
      if (plano && plano.finalizado) finalizado = true;
      cleanReply = rawReply.replace(/```(?:json)?[\s\S]*?```/g, "").trim();
    } catch (e) {}
  }
}

// 3. Fallback: tenta detectar JSON com "finalizado": true
if (!plano) {
  const rawJsonMatch = rawReply.match(/\{[\s\S]*"finalizado"\s*:\s*true[\s\S]*\}/);
  if (rawJsonMatch) {
    try {
      plano = JSON.parse(rawJsonMatch[0]);
      if (plano && plano.finalizado) finalizado = true;
      cleanReply = rawReply.replace(rawJsonMatch[0], "").trim();
    } catch (e) {}
  }
}

return [{
  json: {
    reply: cleanReply,
    plano: plano,
    finalizado: finalizado
  }
}];
